 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Marker cells sit at line endpoints. The 1-colored lines are only
    # drawn between the aligned markers, not continued beyond them.
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    for i, (r1, c1) in enumerate(markers):
        for r2, c2 in markers[i + 1:]:
            if r1 == r2:
                for c in range(min(c1, c2), max(c1, c2) + 1):
                    out[r1][c] = 1
            elif c1 == c2:
                for r in range(min(r1, r2), max(r1, r2) + 1):
                    out[r][c1] = 1
    return out
