    out = [row[:] for row in grid]
    rows = {r for r in range(h) if grid[r][0] == 1 and grid[r][-1] == 1}
    cols = {c for c in range(w) if grid[0][c] == 1 and grid[-1][c] == 1}

    # Draw the line from the edge marker to its aligned opposite-edge marker.
    for r in rows:
        for c in range(w):
            out[r][c] = 1
    for c in cols:
        for r in range(h):
            out[r][c] = 1

    # Recolor any entire 2-object that is intersected by one of those lines.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            intersects = False
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                intersects |= rr in rows or cc in cols
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if intersects:
                for rr, cc in component:
                    out[rr][cc] = 1
    return out
