 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    # Find each 4-connected object. A 2-object struck by a 1-ray turns all
    # the way to 1; the ray passes through it and continues to the boundary.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            obj = []
            while stack:
                rr, cc = stack.pop()
                obj.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            hit = any(grid[rr][0] == 1 or grid[rr][w - 1] == 1 for rr, cc in obj) or \
                  any(grid[0][cc] == 1 or grid[h - 1][cc] == 1 for rr, cc in obj)
            if hit:
                for rr, cc in obj:
                    out[rr][cc] = 1

    # Rays run across the complete row/column, passing through recolored objects.
    for r in range(h):
        if grid[r][0] == 1 or grid[r][w - 1] == 1:
            for c in range(w):
                out[r][c] = 1
    for c in range(w):
        if grid[0][c] == 1 or grid[h - 1][c] == 1:
            for r in range(h):
                out[r][c] = 1
    return out
