    # The 2-object the ray touches changes color as a complete object.
    def fire(r, c, dr, dc):
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == 2:
                stack = [(rr, cc)]
                obj = {(rr, cc)}
                while stack:
                    ar, ac = stack.pop()
                    for nr, nc in ((ar-1,ac),(ar+1,ac),(ar,ac-1),(ar,ac+1)):
                        if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2
                                and (nr,nc) not in obj):
                            obj.add((nr,nc))
                            stack.append((nr,nc))
                for ar, ac in obj:
                    out[ar][ac] = 1
                return
            out[rr][cc] = 1
            rr += dr
            cc += dc

    for r in range(h):
        if grid[r][0] == 1:
            fire(r, 0, 0, 1)
        if grid[r][w-1] == 1:
            fire(r, w-1, 0, -1)
    for c in range(w):
        if grid[0][c] == 1:
